import { createHash } from 'node:crypto';

/*
 * The Spec template is generated by `to-decision-html` from the Spec calibration (design-ADR 0011), so it goes stale
 * when either moves. The template records a hash of what it was generated from; `templateStaleFindings` compares the
 * record with the current sources, and a mismatch fails a test until the template is regenerated.
 *
 * The hash covers the files that decide what a generated template contains:
 * - `skills/to-decision-html/SKILL.md`, every file under `skills/to-decision-html/references/` and every file under
 *   `skills/to-decision-html/assets/`: the skill's instructions, the references they load and the assets (the
 *   toolbar) they tell a page to copy in;
 * - `skills/new-episode/references/spec-calibration.md`, without its "Regenerating the template" section: the
 *   procedure for regenerating changes nothing the template must hold, and the failure message points there.
 *
 * It leaves out `LEARNINGS.md` (lessons the person adds; the skill's instructions take the ones that bind), the
 * evals, `scripts/` (the grader and its fixtures, run when the skill changes, never while a page is built) and
 * `agents/` (the skill's registry entry). None of them changes what a generated template must contain.
 *
 * The record is a `<meta>` in the template's head, so it survives Prettier, which reflows tags and comments.
 */

/** The skill's files, by path relative to the skill folder, and the Spec calibration's text. */
export interface TemplateSources {
  skill: Readonly<Record<string, string>>;
  calibration: string;
}

/** The `<meta name>` that holds the recorded hash in the template's head. */
export const HASH_META = 'spec-template-source-hash';

const REGENERATING = /^## Regenerating the template\s*$/m;
const HEADING = /^## /m;

const lf = (text: string): string => text.replaceAll('\r\n', '\n');

/** The calibration without its "Regenerating the template" section, which runs to the next `## ` heading or the end. */
function calibrationWithoutRegenerating(calibration: string): string {
  const text = lf(calibration);
  const start = REGENERATING.exec(text);
  if (!start) return text;
  const after = text.slice(start.index + start[0].length);
  const next = HEADING.exec(after);
  return text.slice(0, start.index) + (next ? after.slice(next.index) : '');
}

/** The sha256 hex of the sources: files by sorted path, line endings as LF, each length-prefixed against boundary shifts. */
export function templateHash({ skill, calibration }: TemplateSources): string {
  const hash = createHash('sha256');
  const entries = [
    ...Object.keys(skill)
      .sort()
      .map((file) => [`skill:${file}`, lf(skill[file] ?? '')] as const),
    ['calibration', calibrationWithoutRegenerating(calibration)] as const,
  ];
  for (const [name, text] of entries) hash.update(`${name}\0${text.length}\0${text}\0`);
  return hash.digest('hex');
}

/** The hash a template records in its head, or `undefined` when it records none. */
export function recordedTemplateHash(template: string): string | undefined {
  const tag = new RegExp(`<meta\\s[^>]*name="${HASH_META}"[^>]*>`).exec(template);
  return tag ? /content="([^"]*)"/.exec(tag[0])?.[1] : undefined;
}

const HOW =
  'Regenerate it as the "Regenerating the template" section of skills/new-episode/references/spec-calibration.md says; ' +
  'the hash of the current sources is printed by `npm run episode:spec-template-hash`.';

/** One finding when the template's recorded hash is not the current sources' hash, none when it is. */
export function templateStaleFindings(template: string, sources: TemplateSources): string[] {
  const recorded = recordedTemplateHash(template);
  if (recorded === undefined) return [`The Spec template records no hash (<meta name="${HASH_META}">). ${HOW}`];
  const current = templateHash(sources);
  if (recorded === current) return [];
  return [
    `The Spec template is stale: to-decision-html or the Spec calibration changed since it was generated ` +
      `(recorded ${recorded}, current ${current}). ${HOW}`,
  ];
}
